/* HMAC-SHA256 validation against META_APP_SECRET */
const crypto = require('crypto');
const secret = $env.META_APP_SECRET;
if (!secret) {
  throw new Error('META_APP_SECRET not configured in n8n env');
}
const sig = $json.headers?.['x-hub-signature-256'];
if (!sig) {
  throw new Error('Missing X-Hub-Signature-256');
}
const payload = $json.bodyRaw || JSON.stringify($json.body);
const expected = crypto.createHmac('sha256', secret).update(payload, 'utf8').digest('hex');
const provided = sig.startsWith('sha256=') ? sig.slice(7) : sig;
if (expected.length !== provided.length || !crypto.timingSafeEqual(Buffer.from(expected), Buffer.from(provided))) {
  throw new Error('Invalid signature');
}

// Extract event id for idempotency
let eventId = '';
if ($json.body?.entry?.[0]?.changes?.[0]?.value?.messages?.[0]?.id) {
  eventId = $json.body.entry[0].changes[0].value.messages[0].id;
} else if ($json.body?.entry?.[0]?.messaging?.[0]?.message?.mid) {
  eventId = $json.body.entry[0].messaging[0].message.mid;
} else if ($json.body?.entry?.[0]?.id) {
  eventId = $json.body.entry[0].id;
}

return {
  payload: $json.body,
  eventId: eventId,
  eventType: $json.body?.entry?.[0]?.changes ? 'feed_change' : ($json.body?.entry?.[0]?.messaging ? 'messaging' : 'unknown'),
  phoneNumberId: $json.body?.entry?.[0]?.changes?.[0]?.value?.metadata?.phone_number_id ?? null,
  receivedAt: new Date().toISOString()
};

/* Fast 200 response — webhook must return <300ms */
return {
  status: 'accepted',
  queued: true,
  eventId: $json.eventId
};

/* Enqueue for processing + HMAC do corpo re-encaminhado (n8n serializa o objeto tal qual) */
const crypto = require('crypto');
const bodyText = JSON.stringify($json.payload);
return {
  ...$json,
  sigHex: crypto.createHmac('sha256', $env.META_APP_SECRET).update(bodyText, 'utf8').digest('hex')
};

/* Store eventId in n8n KV for dedup (simple in-memory, 24h TTL via workflow cleanup) */
// In production, use Redis or Postgres for persistent dedup
const eventId = $('Enqueue for Processing').first().json.eventId;
return {
  dedupKey: 'webhook_event:' + eventId,
  stored: true
};
